<?php
/** Proof — the vocabulary (spec "Proof", 4): a role, an activity, a category (with a receipt override), a provider (with a mapping), a tax rate added and renamed; archiving one in use keeps it on existing rows; the default tax rate is unique; delete only when unused. */
require __DIR__ . '/lib.php';
$owner = as_member(1); $bea = as_member(28);

echo "1. Consulting roles\n";
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/roles/save.php', ['title' => 'SMOKE Data Engineer', 'description' => 'Pipelines', 'sort_order' => '6']);
$role = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $role > 0 && (string) one('SELECT key FROM consulting_roles WHERE id = :i', ['i' => $role]) === 'smoke_data_engineer' && str_ends_with((string) $b['location'], '/settings/roles/?notice=saved#vocab-row-' . $role), "consulting_role_save: record_id $role, the key made from the title (smoke_data_engineer)");
[$c, $b] = act($owner, '/settings/roles/save.php', ['title' => 'SMOKE Other', 'key' => 'smoke_data_engineer']);
ok($c === 422 && msg($b) === 'The key smoke_data_engineer is already in use.', 'a taken key: 422 in words');
[$c, $b] = act($owner, '/settings/roles/save.php', ['title' => 'SMOKE Other', 'key' => 'Bad Key']);
ok($c === 422 && isset(fields($b)['key']), 'a malformed key: 422 (field key)');
[$c, $b] = act($owner, '/settings/roles/save.php', ['role' => $role, 'title' => 'SMOKE Data Engineer II']);
$log = activity('consulting_role.save', $since);
ok($c === 200 && count($log) === 2 && json_decode((string) $log[1]['after'], true) === ['title' => 'SMOKE Data Engineer II'] && (string) one('SELECT description FROM consulting_roles WHERE id = :i', ['i' => $role]) === 'Pipelines', 'renamed in place; the description kept; the log carries the one changed field');
[$c, $d] = screen($owner, '/settings/roles/');
$row = array_values(array_filter($d['rows'], fn ($x) => $x['id'] === $role))[0];
ok(count($d['rows']) === 6 && $row['in_use'] === 0 && $row['key'] === 'smoke_data_engineer', 'the list: the five seeded and the new one, unused');
$client = mkclient('SMOKE Vocab client');
$eng = mkengagement($client, 'SMOKE vocab eng');
q("INSERT INTO engagement_members (engagement_id, member_id, consulting_role_id, valid_from) VALUES (:e, 26, :r, '2026-01-01')", ['e' => $eng, 'r' => $role]);
[$c, $d] = screen($owner, '/settings/roles/');
ok(array_values(array_filter($d['rows'], fn ($x) => $x['id'] === $role))[0]['in_use'] === 1, 'staffed once: in_use 1');
$body = page($owner, '/settings/roles/')['body'];
ok(str_contains($body, 'id="vocab-row-' . $role . '-archive-btn"') && !str_contains($body, 'id="vocab-row-' . $role . '-delete-btn"'), 'the Delete button is absent once used; Archive stands');
[$c, $b] = act($owner, '/settings/roles/archive.php', ['role' => $role, 'delete' => 'yes']);
ok($c === 422 && msg($b) === 'SMOKE Data Engineer II is in use on 1 record; archive it instead.', 'deleting a used role: 422 in words');
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/roles/archive.php', ['role' => $role]);
ok($c === 200 && one('SELECT archived_at FROM consulting_roles WHERE id = :i', ['i' => $role]) !== null && count(activity('consulting_role.archive', $since)) === 1, 'archived, logged');
ok((int) one('SELECT consulting_role_id FROM engagement_members WHERE engagement_id = :e', ['e' => $eng]) === $role, 'the staffing keeps it');
[$c, $d] = screen($owner, '/settings/roles/');
ok(!in_array($role, array_column($d['rows'], 'id'), true), 'gone from the live list');
[$c, $d] = screen($owner, '/settings/roles/?include_archived=1');
ok(in_array($role, array_column($d['rows'], 'id'), true), 'shown with the archived');
[$c, $b] = act($owner, '/settings/roles/save.php', ['title' => 'SMOKE Data Engineer', 'key' => 'smoke_data_engineer']);
ok($c === 200 && (int) $b['record_id'] !== $role, 'the key is free again for a new live role');
[$c, $b] = act($owner, '/settings/roles/archive.php', ['role' => $role, 'archived' => 'no']);
ok($c === 422 && str_contains(msg($b), 'already'), 'restoring it while the key is taken: 422 (the index)');
[$c, $b] = act($owner, '/settings/roles/archive.php', ['role' => (int) one("SELECT id FROM consulting_roles WHERE key = 'smoke_data_engineer' AND archived_at IS NULL"), 'delete' => 'yes']);
ok($c === 200, 'the unused new one deleted');
[$c, $b] = act($owner, '/settings/roles/archive.php', ['role' => $role, 'archived' => 'no']);
ok($c === 200 && one('SELECT archived_at FROM consulting_roles WHERE id = :i', ['i' => $role]) === null, 'then the old one restored');

echo "2. Activity types and expense categories\n";
[$c, $b] = act($owner, '/settings/activity-types/save.php', ['label' => 'SMOKE Pairing', 'billable_default' => 'no']);
$act = (int) $b['record_id'];
ok($c === 200 && q('SELECT key, billable_default FROM activity_types WHERE id = :i', ['i' => $act])[0] === ['key' => 'smoke_pairing', 'billable_default' => false], 'activity_type_save: key from the label, not billable by default');
[$c, $b] = act($owner, '/settings/categories/save.php', ['label' => 'SMOKE Conference', 'receipt_required_above' => '25', 'default_markup_pct' => '10']);
$cat = (int) $b['record_id'];
ok($c === 200 && q('SELECT receipt_required_above, default_markup_pct FROM expense_categories WHERE id = :i', ['i' => $cat])[0] === ['receipt_required_above' => '25.00', 'default_markup_pct' => '10.00'], 'expense_category_save with a receipt override (25) and a markup (10%)');
[$c, $b] = act($owner, '/settings/categories/save.php', ['category' => $cat, 'receipt_required_above' => '']);
ok($c === 200 && one('SELECT receipt_required_above FROM expense_categories WHERE id = :i', ['i' => $cat]) === null && (string) one('SELECT default_markup_pct FROM expense_categories WHERE id = :i', ['i' => $cat]) === '10.00', 'blanking the override returns it to the settings\'; the markup kept');
[$c, $b] = act($owner, '/settings/categories/save.php', ['category' => $cat, 'default_markup_pct' => '900']);
ok($c === 422 && isset(fields($b)['default_markup_pct']), 'a markup over 500: 422');
[$c, $d] = screen($owner, '/settings/categories/');
ok(count($d['rows']) === 9 && array_values(array_filter($d['rows'], fn ($x) => $x['id'] === $cat))[0]['label'] === 'SMOKE Conference', 'the list: eight seeded and the new one');

echo "3. Providers and tax rates\n";
[$c, $b] = act($owner, '/settings/providers/save.php', ['name' => 'SMOKE Fly.io', 'csv_mapping' => '{"date": "Period", "cost": "Amount"}']);
$prov = (int) $b['record_id'];
ok($c === 200 && (string) one('SELECT provider_key FROM usage_providers WHERE id = :i', ['i' => $prov]) === 'smoke_fly_io' && json_decode((string) one('SELECT csv_mapping FROM usage_providers WHERE id = :i', ['i' => $prov]), true) == ['date' => 'Period', 'cost' => 'Amount'], 'usage_provider_save: the key from the name (smoke_fly_io), the mapping as JSON');
$log = activity('usage_provider.save', 0);
ok(str_contains((string) end($log)['after'], '"has_mapping": true') && !str_contains((string) end($log)['after'], 'Period'), 'the log says a mapping exists, never its content');
[$c, $b] = act($owner, '/settings/providers/save.php', ['provider' => $prov, 'csv_mapping' => 'not json']);
ok($c === 422 && isset(fields($b)['csv_mapping']), 'a mapping that is not JSON: 422');
[$c, $b] = act($owner, '/settings/providers/save.php', ['name' => 'SMOKE Anthropic again', 'provider_key' => 'anthropic']);
ok($c === 422 && msg($b) === 'The key anthropic is already in use.', 'the kernel\'s provider key is unique among live providers');
[$c, $d] = screen($owner, '/settings/providers/');
ok(array_values(array_filter($d['rows'], fn ($x) => $x['id'] === $prov))[0]['csv_mapping'] == ['date' => 'Period', 'cost' => 'Amount'], 'the screen shows the saved mapping (jsonb keeps the keys in its own order)');
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/tax-rates/save.php', ['name' => 'SMOKE VAT', 'rate' => '20']);
$vat = (int) $b['record_id'];
ok($c === 200 && (string) one('SELECT rate FROM tax_rates WHERE id = :i', ['i' => $vat]) === '20.0000' && !one('SELECT is_default FROM tax_rates WHERE id = :i', ['i' => $vat]), 'tax_rate_save: 20.0000, not the default');
[$c, $b] = act($owner, '/settings/tax-rates/save.php', ['tax_rate' => $vat, 'is_default' => 'yes']);
ok($c === 200 && (int) one('SELECT count(*) FROM tax_rates WHERE is_default AND archived_at IS NULL') === 1 && one('SELECT is_default FROM tax_rates WHERE id = :i', ['i' => $vat]) && !one("SELECT is_default FROM tax_rates WHERE name = 'No tax'"), 'made the default: "No tax" is no longer (one default at a time)');
[$c, $b] = act($owner, '/settings/tax-rates/archive.php', ['tax_rate' => $vat]);
ok($c === 422 && msg($b) === 'SMOKE VAT is the default tax rate; make another the default first.', 'archiving the default: 422 in words');
[$c, $b] = act($owner, '/settings/tax-rates/save.php', ['tax_rate' => (int) one("SELECT id FROM tax_rates WHERE name = 'No tax'"), 'is_default' => 'yes']);
[$c, $b] = act($owner, '/settings/tax-rates/save.php', ['tax_rate' => $vat, 'name' => 'SMOKE VAT 20', 'rate' => '20.5']);
ok($c === 200 && q('SELECT name, rate FROM tax_rates WHERE id = :i', ['i' => $vat])[0] === ['name' => 'SMOKE VAT 20', 'rate' => '20.5000'], 'renamed and re-rated');
[$c, $b] = act($owner, '/settings/tax-rates/save.php', ['name' => 'smoke vat 20', 'rate' => '1']);
ok($c === 422 && msg($b) === 'A tax rate named smoke vat 20 already exists.', 'a duplicate name (any case): 422');
[$c, $b] = act($owner, '/settings/tax-rates/save.php', ['name' => 'SMOKE Too much', 'rate' => '100']);
ok($c === 422 && isset(fields($b)['rate']), 'a rate of 100: 422');
[$c, $b] = act($owner, '/settings/tax-rates/archive.php', ['tax_rate' => $vat]);
ok($c === 200 && one('SELECT archived_at FROM tax_rates WHERE id = :i', ['i' => $vat]) !== null, 'no longer the default: archived');
ok(page($bea, '/settings/tax-rates/')['code'] === 403 && page($bea, '/settings/providers/')['code'] === 403, 'the vocabulary screens are the admin\'s');
finish();
